const aiRaw = items[0].json.choices?.[0]?.message?.content || '{}';
const cleaned = aiRaw.replace(/```json|```/g, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  // regex fallback
  const get = (key) => {
    const m = aiRaw.match(new RegExp('"' + key + '"\\s*:\\s*"([^"]*?)"', 'i'));
    return m ? m[1].trim() : '';
  };
  parsed = {
    first_name: get('first_name'), last_name: get('last_name'),
    email: get('email'), company: get('company'),
    job_title: get('job_title'), phone: get('phone'),
    message: get('message'), source: get('source')
  };
}

// Merge: AI values take priority over Normalize, Normalize used as fallback
const norm = $('Normalize lead fields').first().json;
const pick = (ai, fb) => ((ai || '').trim()) || ((fb || '').trim());

return [{
  json: {
    ...norm,
    first_name  : pick(parsed.first_name,  norm.first_name),
    last_name   : pick(parsed.last_name,   norm.last_name),
    email       : (parsed.email || norm.email || '').toLowerCase().trim(),
    company     : pick(parsed.company,     norm.company),
    job_title   : pick(parsed.job_title,   norm.job_title),
    phone       : pick(parsed.phone,       norm.phone),
    message     : pick(parsed.message,     norm.message),
    source      : pick(parsed.source,      norm.source) || 'webhook',
    submitted_at: norm.submitted_at || new Date().toISOString(),
    _ai_extracted: Object.keys(parsed).some(k => parsed[k])
  }
}];

const hunterResp = items[0].json;
// Get the full lead data from the previous enrichment step
const lead = $('Enrich from email domain').first().json;

// Safely extract Hunter data — handles errors / empty responses gracefully
const d = (hunterResp.data) || {};
const hunterCompany   = (d.organization || '').trim();
const hunterIndustry  = (d.industry     || '').trim();
const hunterSize      = d.size          || '';
const hunterCountry   = (d.country      || '').trim();
const hunterEnriched  = !!hunterCompany;

return [{
  json: {
    ...lead,
    // Prefer Hunter company name over domain-derived one if available
    enriched_company     : hunterCompany || lead.enriched_company,
    hunter_company       : hunterCompany,
    hunter_industry      : hunterIndustry,
    hunter_employee_count: hunterSize,
    hunter_country       : hunterCountry,
    hunter_enriched      : hunterEnriched
  }
}];

const raw = items[0].json.choices?.[0]?.message?.content || '{}';
const cleaned = raw.replace(/```json|```/g, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = {
    score: 20, tier: 'cold',
    budget: 5, authority: 5, need: 5, timeline: 5,
    reasoning: 'AI response could not be parsed — review manually',
    recommended_action: 'Check the Parse AI score node output for raw response'
  };
}
return [{ json: { ...items[0].json, ...parsed } }];

const item = items[0].json;
const email = (item.email || '').toLowerCase();
const domain = email.includes('@') ? email.split('@')[1] : '';
const domainBase = domain.split('.')[0];
const companyFromDomain = domainBase.charAt(0).toUpperCase() + domainBase.slice(1);

const personalProviders = ['gmail','yahoo','hotmail','outlook','protonmail','icloud','aol','live','msn','me','zoho'];
const isPersonalEmail = personalProviders.some(p => domain.includes(p));
const isWorkEmail = !isPersonalEmail && domain !== '';

const title = (item.job_title || '').toLowerCase();
const seniorKw = ['ceo','cto','coo','cfo','cpo','chief','founder','co-founder','president','vp','vice president','director','head of','owner','partner','managing'];
const juniorKw = ['intern','student','trainee','junior','assistant','associate','coordinator','entry level'];
const midKw = ['manager','lead','senior','principal','architect','specialist','supervisor'];

let seniority = 'mid';
if (seniorKw.some(k => title.includes(k))) seniority = 'senior';
else if (juniorKw.some(k => title.includes(k))) seniority = 'junior';
else if (midKw.some(k => title.includes(k))) seniority = 'mid';

return [{
  json: {
    ...item,
    domain,
    enriched_company: item.company || companyFromDomain || '',
    enriched_job_title: item.job_title || '',
    seniority,
    is_personal_email: isPersonalEmail,
    is_work_email: isWorkEmail,
    company_domain: domain
  }
}];
